using System.Reflection;

namespace BatchRenameStudio.Core;

/// <summary>Marks a <see cref="RuleStep"/> implementation and carries its wire name.</summary>
[AttributeUsage(AttributeTargets.Class, Inherited = false)]
public sealed class StepOpAttribute : Attribute
{
    public StepOpAttribute(string op, string display)
    {
        Op = op;
        Display = display;
    }

    /// <summary>Value of the <c>"op"</c> discriminator in rules.json / trace output.</summary>
    public string Op { get; }

    /// <summary>Human readable name shown in the GUI.</summary>
    public string Display { get; }

    /// <summary>One line explanation shown in the GUI parameter panel.</summary>
    public string Description { get; set; } = "";

    /// <summary>Grouping label used by the GUI operation picker.</summary>
    public string Group { get; set; } = "";
}

/// <summary>Marks a step property as a serialized + user editable parameter.</summary>
[AttributeUsage(AttributeTargets.Property, Inherited = false)]
public sealed class StepFieldAttribute : Attribute
{
    public StepFieldAttribute(string json, string label, int order)
    {
        Json = json;
        Label = label;
        Order = order;
    }

    /// <summary>Property name used in rules.json.</summary>
    public string Json { get; }

    public string Label { get; }

    public int Order { get; }

    /// <summary>Comma separated closed set of legal values; empty means free text.</summary>
    public string Choices { get; set; } = "";

    public string Hint { get; set; } = "";
}

public sealed class StepFieldMeta
{
    public StepFieldMeta(PropertyInfo prop, StepFieldAttribute attr)
    {
        Property = prop;
        Json = attr.Json;
        Label = attr.Label;
        Order = attr.Order;
        Hint = attr.Hint;
        Choices = attr.Choices.Length == 0
            ? Array.Empty<string>()
            : attr.Choices.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
    }

    public PropertyInfo Property { get; }
    public string Json { get; }
    public string Label { get; }
    public int Order { get; }
    public string Hint { get; }
    public string[] Choices { get; }
    public Type Type => Property.PropertyType;

    public object? Get(RuleStep step) => Property.GetValue(step);

    public void Set(RuleStep step, object? value) => Property.SetValue(step, value);
}

public sealed class StepMeta
{
    public StepMeta(Type type)
    {
        var attr = type.GetCustomAttribute<StepOpAttribute>()
                   ?? throw new InvalidOperationException($"{type.Name} is missing [StepOp].");
        Type = type;
        Op = attr.Op;
        Display = attr.Display;
        Description = attr.Description;
        Group = attr.Group;
        Fields = type.GetProperties(BindingFlags.Public | BindingFlags.Instance)
            .Select(p => (p, a: p.GetCustomAttribute<StepFieldAttribute>()))
            .Where(t => t.a is not null)
            .Select(t => new StepFieldMeta(t.p, t.a!))
            .OrderBy(f => f.Order)
            .ThenBy(f => f.Json, StringComparer.Ordinal)
            .ToArray();
    }

    public Type Type { get; }
    public string Op { get; }
    public string Display { get; }
    public string Description { get; }
    public string Group { get; }
    public IReadOnlyList<StepFieldMeta> Fields { get; }

    public RuleStep Create() => (RuleStep)Activator.CreateInstance(Type)!;
}

/// <summary>
/// Static catalogue of the 14 operations. The order here is the order shown in the GUI
/// picker and is intentionally explicit rather than reflection-scanned, so it is stable.
/// </summary>
public static class StepRegistry
{
    private static readonly Type[] Types =
    {
        typeof(Ops.ReplaceStep),
        typeof(Ops.InsertStep),
        typeof(Ops.RemoveStep),
        typeof(Ops.SequenceStep),
        typeof(Ops.CaseStep),
        typeof(Ops.ExtensionStep),
        typeof(Ops.PadStep),
        typeof(Ops.TrimStep),
        typeof(Ops.SlugStep),
        typeof(Ops.TranslateStep),
        typeof(Ops.NumberFormatStep),
        typeof(Ops.ExtractStep),
        typeof(Ops.TemplateStep),
        typeof(Ops.DedupeCharsStep),
    };

    private static readonly StepMeta[] AllMeta = Types.Select(t => new StepMeta(t)).ToArray();

    private static readonly Dictionary<string, StepMeta> ByOpName =
        AllMeta.ToDictionary(m => m.Op, StringComparer.Ordinal);

    private static readonly Dictionary<Type, StepMeta> ByType =
        AllMeta.ToDictionary(m => m.Type);

    public static IReadOnlyList<StepMeta> All => AllMeta;

    public static StepMeta? Find(string op) =>
        ByOpName.TryGetValue(op, out var m) ? m : null;

    public static StepMeta? MetaOf(RuleStep step) =>
        ByType.TryGetValue(step.GetType(), out var m) ? m : null;

    public static RuleStep Create(string op) =>
        Find(op)?.Create() ?? throw new ArgumentException($"Unknown operation '{op}'.", nameof(op));
}

