using System.Text.Json.Nodes;

namespace BatchRenameStudio.Core;

/// <summary>Mutable per-file state threaded through the step chain.</summary>
public sealed class WorkState
{
    public WorkState(string target, string ext)
    {
        Target = target;
        Ext = ext;
    }

    /// <summary>
    /// The "target string" of spec rule 3: the base name under applyTo "name",
    /// the whole file name under applyTo "nameAndExtension".
    /// </summary>
    public string Target { get; set; }

    /// <summary>
    /// The live extension (no dot). Only meaningful under applyTo "name", where the
    /// <c>extension</c> op mutates it without touching <see cref="Target"/>.
    /// </summary>
    public string Ext { get; set; }
}

public enum ApplyTo
{
    Name,
    NameAndExtension,
}

/// <summary>Immutable facts about the file currently being processed.</summary>
public sealed class FileContext
{
    public FileContext(int index, string originalName, string originalBase, string originalExt, ApplyTo applyTo)
    {
        Index = index;
        OriginalName = originalName;
        OriginalBase = originalBase;
        OriginalExt = originalExt;
        ApplyTo = applyTo;
    }

    /// <summary>0-based position in processing order (spec rule 5).</summary>
    public int Index { get; }

    public string OriginalName { get; }

    public string OriginalBase { get; }

    /// <summary>Extension of the ORIGINAL file per spec rule 2, without dot. Never mutated.</summary>
    public string OriginalExt { get; }

    public ApplyTo ApplyTo { get; }

    private readonly List<string> _notes = new();

    public IReadOnlyList<string> Notes => _notes;

    /// <summary>
    /// Records a non-fatal diagnostic (e.g. a malformed regex that was skipped). Notes only
    /// ever surface in the free-form <c>reason</c> field; they never influence status.
    /// </summary>
    public void Note(string message)
    {
        if (!_notes.Contains(message))
        {
            _notes.Add(message);
        }
    }
}

public abstract class RuleStep
{
    /// <summary>Wire name of this operation.</summary>
    public virtual string OpName => StepRegistry.MetaOf(this)?.Op ?? GetType().Name;

    public abstract void Apply(WorkState state, FileContext context);

    /// <summary>Short one-line description used in the GUI rule list.</summary>
    public abstract string Summary();

    public virtual JsonObject ToJson() => StepJson.DefaultToJson(this);

    public RuleStep Clone() => StepJson.FromJson(ToJson());
}

/// <summary>
/// Placeholder for an <c>op</c> value this build does not know. It is a no-op, but it keeps
/// its slot in the array so that trace step indices stay aligned with the input rules.json
/// (the contract demands one trace entry per step, in array order).
/// </summary>
public sealed class UnknownStep : RuleStep
{
    private readonly JsonObject _raw;

    public UnknownStep(string op, JsonObject? raw = null)
    {
        UnknownOp = op;
        _raw = raw ?? new JsonObject { ["op"] = op };
    }

    public string UnknownOp { get; }

    public override string OpName => UnknownOp;

    public override void Apply(WorkState state, FileContext context) =>
        context.Note($"unknown op '{UnknownOp}' ignored");

    public override string Summary() => $"unknown op '{UnknownOp}' (ignored)";

    public override JsonObject ToJson() => (JsonObject)_raw.DeepClone();
}

