using System.Globalization;

namespace BatchRenameStudio.Core;

/// <summary>File-name arithmetic exactly as pinned by spec rules 2, 6 and 7.</summary>
public static class NameUtil
{
    /// <summary>Characters rejected outright by spec rule 7.</summary>
    public const string ForbiddenChars = "<>:\"/\\|?*";

    public const int MaxNameLength = 255;

    private static readonly HashSet<string> ReservedNames = BuildReserved();

    private static HashSet<string> BuildReserved()
    {
        var set = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "CON", "PRN", "AUX", "NUL" };
        for (int i = 1; i <= 9; i++)
        {
            set.Add("COM" + i.ToString(CultureInfo.InvariantCulture));
            set.Add("LPT" + i.ToString(CultureInfo.InvariantCulture));
        }

        return set;
    }

    /// <summary>
    /// Spec rule 2. <c>dot</c> is the index of the LAST '.'; when <c>dot &gt; 0</c> the name splits
    /// there, otherwise the whole name is the base and the extension is empty
    /// (so ".gitignore" keeps base ".gitignore").
    /// </summary>
    public static (string Base, string Ext) Split(string name)
    {
        int dot = name.LastIndexOf('.');
        if (dot > 0)
        {
            return (name.Substring(0, dot), name.Substring(dot + 1));
        }

        return (name, string.Empty);
    }

    /// <summary>Spec rule 6 reassembly.</summary>
    public static string Join(string baseName, string ext) =>
        ext.Length > 0 ? baseName + "." + ext : baseName;

    /// <summary>
    /// Spec rule 7, first bullet. Returns true when the proposed name may not be written,
    /// together with a short human readable reason.
    /// </summary>
    public static bool IsInvalid(string proposed, out string reason)
    {
        if (proposed.Length == 0)
        {
            reason = "proposed name is empty";
            return true;
        }

        if (proposed.Length > MaxNameLength)
        {
            reason = $"proposed name is {proposed.Length} characters (max {MaxNameLength})";
            return true;
        }

        foreach (char c in proposed)
        {
            if (c < ' ')
            {
                reason = $"contains control character U+{(int)c:X4}";
                return true;
            }

            if (ForbiddenChars.IndexOf(c) >= 0)
            {
                reason = $"contains forbidden character '{c}'";
                return true;
            }
        }

        var (baseName, _) = Split(proposed);
        if (ReservedNames.Contains(baseName))
        {
            reason = $"'{baseName}' is a reserved device name";
            return true;
        }

        reason = string.Empty;
        return false;
    }

    public static ApplyTo ParseApplyTo(string? value) =>
        string.Equals(value, "nameAndExtension", StringComparison.OrdinalIgnoreCase)
            ? ApplyTo.NameAndExtension
            : ApplyTo.Name;

    public static string ApplyToWire(ApplyTo value) =>
        value == ApplyTo.NameAndExtension ? "nameAndExtension" : "name";

    /// <summary>Zero-pads a counter, keeping any minus sign in front of the padding.</summary>
    public static string PadNumber(long value, int width)
    {
        if (value < 0)
        {
            return "-" + (-value).ToString(CultureInfo.InvariantCulture).PadLeft(width, '0');
        }

        return value.ToString(CultureInfo.InvariantCulture).PadLeft(width, '0');
    }
}

