using System.Text;
using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core.Ops;

/// <summary>Shared helpers for the regex-backed operations.</summary>
internal static class RegexSupport
{
    /// <summary>Guards the GUI (and the CLI) against catastrophic backtracking.</summary>
    internal static readonly TimeSpan Timeout = TimeSpan.FromSeconds(1);

    internal const RegexOptions BaseOptions = RegexOptions.CultureInvariant;

    internal static RegexOptions Options(bool ignoreCase) =>
        ignoreCase ? BaseOptions | RegexOptions.IgnoreCase : BaseOptions;
}

[StepOp("replace", "Replace", Group = "Text", Description = "Replace every occurrence of a literal or regular expression. An empty Find is a no-op.")]
public sealed class ReplaceStep : RuleStep
{
    [StepField("find", "Find", 1, Hint = "Literal text, or a .NET regex when Regex is ticked.")]
    public string Find { get; set; } = "";

    [StepField("replaceWith", "Replace with", 2, Hint = "$1 group references are honoured in regex mode.")]
    public string ReplaceWith { get; set; } = "";

    [StepField("regex", "Regex", 3)]
    public bool UseRegex { get; set; }

    [StepField("ignoreCase", "Ignore case", 4)]
    public bool IgnoreCase { get; set; }

    public override void Apply(WorkState state, FileContext context)
    {
        if (Find.Length == 0)
        {
            return; // Spec: an empty find is a no-op, never an error.
        }

        if (UseRegex)
        {
            try
            {
                state.Target = Regex.Replace(
                    state.Target, Find, ReplaceWith, RegexSupport.Options(IgnoreCase), RegexSupport.Timeout);
            }
            catch (ArgumentException)
            {
                context.Note($"replace: invalid regex '{Find}' skipped");
            }
            catch (RegexMatchTimeoutException)
            {
                context.Note("replace: regex timed out, step skipped");
            }
        }
        else
        {
            state.Target = state.Target.Replace(
                Find, ReplaceWith, IgnoreCase ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal);
        }
    }

    public override string Summary()
    {
        var flags = (UseRegex ? " regex" : "") + (IgnoreCase ? " ignore-case" : "");
        return $"\"{Find}\" → \"{ReplaceWith}\"{flags}";
    }
}

[StepOp("insert", "Insert", Group = "Text", Description = "Insert literal text at the front, the end, or a 0-based index (clamped).")]
public sealed class InsertStep : RuleStep
{
    [StepField("text", "Text", 1)]
    public string Text { get; set; } = "";

    [StepField("position", "Position", 2, Choices = "prefix,suffix,index")]
    public string Position { get; set; } = "prefix";

    [StepField("index", "Index", 3, Hint = "Used only when Position is 'index'. Clamped to [0, length].")]
    public int Index { get; set; }

    public override void Apply(WorkState state, FileContext context)
    {
        switch (Position)
        {
            case "suffix":
                state.Target += Text;
                break;
            case "index":
                int at = Math.Clamp(Index, 0, state.Target.Length);
                state.Target = state.Target.Insert(at, Text);
                break;
            default:
