using System.Globalization;
using System.Text;
using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core.Ops;

[StepOp("pad", "Pad to length", Group = "Layout", Description = "Grow the target to an exact length with a single fill character. No change when it is already that long, or when Fill is not exactly one character.")]
public sealed class PadStep : RuleStep
{
    [StepField("length", "Length", 1)]
    public int Length { get; set; } = 10;

    [StepField("fill", "Fill", 2, Hint = "Exactly one character, otherwise the step does nothing.")]
    public string Fill { get; set; } = "_";

    [StepField("side", "Side", 3, Choices = "left,right")]
    public string Side { get; set; } = "left";

    public override void Apply(WorkState state, FileContext context)
    {
        if (Fill.Length != 1)
        {
            context.Note("pad: fill must be exactly one character, step skipped");
            return;
        }

        int need = Length - state.Target.Length;
        if (need <= 0)
        {
            return;
        }

        string padding = new string(Fill[0], need);
        state.Target = Side == "right" ? state.Target + padding : padding + state.Target;
    }

    public override string Summary() => $"pad to {Length} with \"{Fill}\" on {Side}";
}

[StepOp("trim", "Trim characters", Group = "Layout", Description = "Repeatedly strip characters belonging to the given set from one or both ends. An empty set is a no-op.")]
public sealed class TrimStep : RuleStep
{
    [StepField("chars", "Characters", 1, Hint = "A set, not a sequence: \" _-\" trims spaces, underscores and dashes.")]
    public string Chars { get; set; } = " _-";

    [StepField("side", "Side", 2, Choices = "both,left,right")]
    public string Side { get; set; } = "both";

    public override void Apply(WorkState state, FileContext context)
    {
        if (Chars.Length == 0)
        {
            return;
        }

        var set = new HashSet<char>(Chars);
        string target = state.Target;
        int start = 0;
        int end = target.Length;

        if (Side is "both" or "left")
        {
            while (start < end && set.Contains(target[start]))
            {
                start++;
            }
        }

        if (Side is "both" or "right")
        {
            while (end > start && set.Contains(target[end - 1]))
            {
                end--;
            }
        }

        state.Target = target.Substring(start, end - start);
    }

    public override string Summary() => $"trim \"{Chars}\" ({Side})";
}

[StepOp("slug", "Slugify", Group = "Text", Description = "Lowercase, then collapse every run of characters outside [a-z0-9] into one separator, then strip leading/trailing separators.")]
public sealed class SlugStep : RuleStep
{
    [StepField("separator", "Separator", 1, Hint = "Empty removes the runs entirely.")]
    public string Separator { get; set; } = "-";

    public override void Apply(WorkState state, FileContext context)
    {
        string lowered = state.Target.ToLowerInvariant();
        var sb = new StringBuilder(lowered.Length);
        bool inRun = false;

        foreach (char c in lowered)
        {
            if (c is >= 'a' and <= 'z' or >= '0' and <= '9')
            {
                sb.Append(c);
                inRun = false;
            }
            else if (!inRun)
            {
                sb.Append(Separator);
                inRun = true;
            }
        }

        string result = sb.ToString();
        if (Separator.Length > 0)
        {
            while (result.StartsWith(Separator, StringComparison.Ordinal))
            {
                result = result.Substring(Separator.Length);
            }

            while (result.EndsWith(Separator, StringComparison.Ordinal))
            {
                result = result.Substring(0, result.Length - Separator.Length);
            }
        }

        state.Target = result;
    }

    public override string Summary() => $"slug (separator \"{Separator}\")";
}

[StepOp("translate", "Translate characters", Group = "Text", Description = "Positional character mapping. Characters mapped past the end of To are deleted; the first mapping wins when From repeats.")]
public sealed class TranslateStep : RuleStep
{
    [StepField("from", "From", 1)]
    public string From { get; set; } = "";

    [StepField("to", "To", 2, Hint = "Shorter than From ⇒ the surplus characters are deleted.")]
    public string To { get; set; } = "";

    public override void Apply(WorkState state, FileContext context)
    {
        if (From.Length == 0)
        {
            return;
        }

        var map = new Dictionary<char, char?>();
        for (int k = 0; k < From.Length; k++)
        {
            if (!map.ContainsKey(From[k]))
            {
                map[From[k]] = k < To.Length ? To[k] : null;
            }
        }

        var sb = new StringBuilder(state.Target.Length);
        foreach (char c in state.Target)
        {
            if (map.TryGetValue(c, out char? mapped))
            {
                if (mapped.HasValue)
                {
                    sb.Append(mapped.Value);
                }
            }
            else
            {
                sb.Append(c);
            }
        }

        state.Target = sb.ToString();
    }

    public override string Summary() => $"translate \"{From}\" → \"{To}\"";
}

[StepOp("numberFormat", "Normalise number width", Group = "Numbering", Description = "Left-pad the FIRST run of digits with zeroes to the requested width. Longer runs and digit-free names are untouched.")]
public sealed class NumberFormatStep : RuleStep
{
    [StepField("width", "Width", 1)]
    public int Width { get; set; } = 4;

    public override void Apply(WorkState state, FileContext context)
    {
        string target = state.Target;
        int i = 0;
        while (i < target.Length && !IsDigit(target[i]))
        {
            i++;
        }

        if (i == target.Length)
        {
            return;
        }

        int j = i;
        while (j < target.Length && IsDigit(target[j]))
        {
            j++;
        }

        int runLength = j - i;
        if (runLength >= Width)
        {
            return;
        }

        state.Target = string.Concat(
            target.AsSpan(0, i),
            new string('0', Width - runLength),
            target.AsSpan(i, runLength),
            target.AsSpan(j));
    }

    private static bool IsDigit(char c) => c is >= '0' and <= '9';

    public override string Summary() => $"number width {Width}";
}

[StepOp("extract", "Extract by regex", Group = "Text", Description = "Replace the whole target with the first match (group 0) or one of its groups. No match, or an out-of-range group, yields an empty target.")]
public sealed class ExtractStep : RuleStep
{
    [StepField("pattern", "Pattern", 1, Hint = @"e.g. \d+")]
    public string Pattern { get; set; } = @"\d+";

    [StepField("group", "Group", 2, Hint = "0 = the whole match.")]
    public int Group { get; set; }

    public override void Apply(WorkState state, FileContext context)
    {
        Match match;
        try
        {
            match = Regex.Match(state.Target, Pattern, RegexSupport.BaseOptions, RegexSupport.Timeout);
        }
        catch (ArgumentException)
        {
            context.Note($"extract: invalid regex '{Pattern}' skipped");
            return;
        }
        catch (RegexMatchTimeoutException)
        {
            context.Note("extract: regex timed out, step skipped");
            return;
        }

        if (!match.Success || Group < 0 || Group >= match.Groups.Count)
        {
            state.Target = string.Empty;
            return;
        }

        state.Target = match.Groups[Group].Value;
    }

    public override string Summary() => $"extract /{Pattern}/ group {Group}";
}

[StepOp("template", "Template", Group = "Text", Description = "Rebuild the target from a format string. Tokens: {name} {ext} {len} {n:000}; anything else in braces stays literal.")]
public sealed class TemplateStep : RuleStep
{
    private static readonly Regex TokenPattern = new(@"\{([^{}]*)\}", RegexOptions.CultureInvariant);
    private static readonly Regex CounterToken = new(@"^n:(0+)$", RegexOptions.CultureInvariant);

    [StepField("format", "Format", 1, Hint = "e.g. {name}-{ext}-{n:000}")]
    public string Format { get; set; } = "{name}-{n:000}";

    public override void Apply(WorkState state, FileContext context)
    {
        string current = state.Target;
        string length = current.Length.ToString(CultureInfo.InvariantCulture);

        state.Target = TokenPattern.Replace(Format, m =>
        {
            string key = m.Groups[1].Value;
            switch (key)
            {
                case "name":
                    return current;
                case "ext":
                    return context.OriginalExt;
                case "len":
                    return length;
            }

            var counter = CounterToken.Match(key);
            if (counter.Success)
            {
                return NameUtil.PadNumber(context.Index + 1, counter.Groups[1].Value.Length);
            }

            return m.Value; // Unrecognised {...} sequences are left in place literally.
        });
    }

    public override string Summary() => $"template \"{Format}\"";
}

[StepOp("dedupeChars", "Collapse repeats", Group = "Layout", Description = "Collapse every run of the same character to a single occurrence. Case-sensitive.")]
public sealed class DedupeCharsStep : RuleStep
{
    public override void Apply(WorkState state, FileContext context)
    {
        string target = state.Target;
        if (target.Length < 2)
        {
            return;
        }

        var sb = new StringBuilder(target.Length);
        char previous = target[0];
        sb.Append(previous);
        for (int i = 1; i < target.Length; i++)
        {
            if (target[i] != previous)
            {
                sb.Append(target[i]);
            }

            previous = target[i];
        }

        state.Target = sb.ToString();
    }

    public override string Summary() => "collapse repeated characters";
}

