using System.Globalization;
using System.Text.Json.Nodes;

namespace BatchRenameStudio.Core;

public enum SortMode
{
    Name,
    Created,
    Modified,
}

/// <summary>In-memory form of rules.json.</summary>
public sealed class RuleSet
{
    public ApplyTo ApplyTo { get; set; } = ApplyTo.Name;

    public SortMode Sort { get; set; } = SortMode.Name;

    public List<RuleStep> Steps { get; } = new();

    public RuleSet Clone()
    {
        var copy = new RuleSet { ApplyTo = ApplyTo, Sort = Sort };
        foreach (var step in Steps)
        {
            copy.Steps.Add(step.Clone());
        }

        return copy;
    }

    public static SortMode ParseSort(string? value) => value?.ToLowerInvariant() switch
    {
        "created" => SortMode.Created,
        "modified" => SortMode.Modified,
        _ => SortMode.Name,
    };

    public static string SortWire(SortMode mode) => mode switch
    {
        SortMode.Created => "created",
        SortMode.Modified => "modified",
        _ => "name",
    };
}

/// <summary>Reads and writes rules.json, tolerating missing or oddly typed members.</summary>
public static class StepJson
{
    public static RuleSet ParseRuleSet(string json)
    {
        JsonNode? root;
        try
        {
            root = JsonNode.Parse(json, documentOptions: new System.Text.Json.JsonDocumentOptions
            {
                CommentHandling = System.Text.Json.JsonCommentHandling.Skip,
                AllowTrailingCommas = true,
            });
        }
        catch (System.Text.Json.JsonException ex)
        {
            throw new RuleSetException($"rules file is not valid JSON: {ex.Message}", ex);
        }

        if (root is not JsonObject obj)
        {
            throw new RuleSetException("rules file must contain a JSON object at the root.");
        }

        var set = new RuleSet
        {
            ApplyTo = NameUtil.ParseApplyTo(AsString(obj["applyTo"], "name")),
            Sort = RuleSet.ParseSort(AsString(obj["sort"], "name")),
        };

        if (obj["steps"] is JsonArray steps)
        {
            foreach (var node in steps)
            {
                if (node is JsonObject stepObj)
                {
                    set.Steps.Add(FromJson(stepObj));
                }
            }
        }

        return set;
    }

    public static RuleSet LoadRuleSet(string path) => ParseRuleSet(File.ReadAllText(path));

    public static JsonObject ToJson(RuleSet set)
    {
        var steps = new JsonArray();
        foreach (var step in set.Steps)
        {
            steps.Add(step.ToJson());
        }

        return new JsonObject
        {
            ["applyTo"] = NameUtil.ApplyToWire(set.ApplyTo),
            ["sort"] = RuleSet.SortWire(set.Sort),
            ["steps"] = steps,
        };
    }

    public static RuleStep FromJson(JsonObject obj)
    {
        string op = AsString(obj["op"], "");
        var meta = StepRegistry.Find(op);
        if (meta is null)
        {
            return new UnknownStep(op, (JsonObject)obj.DeepClone());
        }

        var step = meta.Create();
        foreach (var field in meta.Fields)
        {
            var node = obj[field.Json];
            if (node is null)
            {
                continue;
            }

            if (field.Type == typeof(string))
            {
                field.Set(step, AsString(node, (string?)field.Get(step) ?? ""));
            }
            else if (field.Type == typeof(int))
            {
                field.Set(step, AsInt(node, (int)(field.Get(step) ?? 0)));
            }
            else if (field.Type == typeof(bool))
            {
                field.Set(step, AsBool(node, (bool)(field.Get(step) ?? false)));
            }
        }

        return step;
    }

    public static JsonObject DefaultToJson(RuleStep step)
    {
        var meta = StepRegistry.MetaOf(step);
        var obj = new JsonObject { ["op"] = step.OpName };
        if (meta is null)
        {
            return obj;
        }

        foreach (var field in meta.Fields)
        {
            object? value = field.Get(step);
            obj[field.Json] = value switch
            {
                string s => JsonValue.Create(s),
                int i => JsonValue.Create(i),
                bool b => JsonValue.Create(b),
                _ => null,
            };
        }

        return obj;
    }

    internal static string AsString(JsonNode? node, string fallback)
    {
        if (node is not JsonValue value)
        {
            return fallback;
        }

        if (value.TryGetValue(out string? s))
        {
            return s ?? fallback;
        }

        if (value.TryGetValue(out bool b))
        {
            return b ? "true" : "false";
        }

        if (value.TryGetValue(out long l))
        {
            return l.ToString(CultureInfo.InvariantCulture);
        }

        if (value.TryGetValue(out double d))
        {
            return d.ToString(CultureInfo.InvariantCulture);
        }

        return fallback;
    }

    internal static int AsInt(JsonNode? node, int fallback)
    {
        if (node is not JsonValue value)
        {
            return fallback;
        }

        if (value.TryGetValue(out int i))
        {
            return i;
        }

        if (value.TryGetValue(out double d) && d >= int.MinValue && d <= int.MaxValue)
        {
            return (int)d;
        }

        if (value.TryGetValue(out string? s) &&
            int.TryParse(s, NumberStyles.Integer, CultureInfo.InvariantCulture, out int parsed))
        {
            return parsed;
        }

        if (value.TryGetValue(out bool b))
        {
            return b ? 1 : 0;
        }

        return fallback;
    }

    internal static bool AsBool(JsonNode? node, bool fallback)
    {
        if (node is not JsonValue value)
        {
            return fallback;
        }

        if (value.TryGetValue(out bool b))
        {
            return b;
        }

        if (value.TryGetValue(out string? s))
        {
            return string.Equals(s, "true", StringComparison.OrdinalIgnoreCase) || s == "1";
        }

        if (value.TryGetValue(out double d))
        {
            return d != 0;
        }

        return fallback;
    }
}

public sealed class RuleSetException : Exception
{
    public RuleSetException(string message, Exception? inner = null) : base(message, inner)
    {
    }
}

