namespace BatchRenameStudio.Core;

public static class ItemStatus
{
    public const string Ok = "ok";
    public const string Collision = "collision";
    public const string Unchanged = "unchanged";
    public const string Invalid = "invalid";
}

public sealed record TraceStep(int Index, string Op, string Before, string After)
{
    public bool Changed => !string.Equals(Before, After, StringComparison.Ordinal);
}

public sealed class PlanItem
{
    public required string Original { get; init; }

    public required string Proposed { get; set; }

    public string Status { get; set; } = ItemStatus.Ok;

    public string Reason { get; set; } = "";

    public required IReadOnlyList<TraceStep> Steps { get; init; }

    /// <summary>Absolute path of the source file; not part of the wire contract.</summary>
    public required string FullPath { get; init; }
}

public sealed class PlanSummary
{
    public int Total { get; set; }
    public int Ok { get; set; }
    public int Collision { get; set; }
    public int Unchanged { get; set; }
    public int Invalid { get; set; }
}

public sealed class EngineResult
{
    public required IReadOnlyList<PlanItem> Items { get; init; }

    public required PlanSummary Summary { get; init; }

    public required string Directory { get; init; }
}

/// <summary>
/// The single source of truth for --plan, --explain and the GUI preview: one pass produces
/// the proposed names, the per-step trace and the status for every file.
/// </summary>
public static class RenameEngine
{
    public static EngineResult Run(string directory, RuleSet rules)
    {
        var info = new DirectoryInfo(directory);
        if (!info.Exists)
        {
            throw new DirectoryNotFoundException($"Directory not found: {directory}");
        }

        // Rule 1: regular files directly inside the folder. GetFiles never returns directories,
        // and without a search option it never recurses.
        var files = Sort(info.GetFiles(), rules.Sort);

        var items = new List<PlanItem>(files.Count);
        for (int i = 0; i < files.Count; i++)
        {
            items.Add(Evaluate(files[i], i, rules));
        }

        AssignStatuses(items);

        var summary = new PlanSummary { Total = items.Count };
        foreach (var item in items)
        {
            switch (item.Status)
            {
                case ItemStatus.Ok: summary.Ok++; break;
                case ItemStatus.Collision: summary.Collision++; break;
                case ItemStatus.Unchanged: summary.Unchanged++; break;
                case ItemStatus.Invalid: summary.Invalid++; break;
            }
        }

        return new EngineResult { Items = items, Summary = summary, Directory = info.FullName };
    }

    /// <summary>
    /// Rule 5. "name" is ordinal, case-sensitive. The timestamp modes fall back to the same
    /// ordinal comparison on ties so that rule 9 (determinism) holds for equal timestamps.
    /// </summary>
    private static List<FileInfo> Sort(FileInfo[] files, SortMode mode) => mode switch
    {
        SortMode.Created => files
            .OrderBy(f => f.CreationTimeUtc)
            .ThenBy(f => f.Name, StringComparer.Ordinal)
            .ToList(),
        SortMode.Modified => files
            .OrderBy(f => f.LastWriteTimeUtc)
            .ThenBy(f => f.Name, StringComparer.Ordinal)
            .ToList(),
        _ => files
            .OrderBy(f => f.Name, StringComparer.Ordinal)
            .ToList(),
    };

    private static PlanItem Evaluate(FileInfo file, int index, RuleSet rules)
    {
        string name = file.Name;
        var (baseName, ext) = NameUtil.Split(name);
        var context = new FileContext(index, name, baseName, ext, rules.ApplyTo);

        // Rule 3: the target string is the base name, or the whole name.
        var state = rules.ApplyTo == ApplyTo.Name
            ? new WorkState(baseName, ext)
            : new WorkState(name, ext);

        var trace = new List<TraceStep>(rules.Steps.Count);
        for (int s = 0; s < rules.Steps.Count; s++)
        {
            var step = rules.Steps[s];
            string before = state.Target;
            step.Apply(state, context);
            // One entry per step, including no-ops (then before == after).
            trace.Add(new TraceStep(s, step.OpName, before, state.Target));
        }

        // Rule 6: reassemble only when the extension was held out of the target string.
        string proposed = rules.ApplyTo == ApplyTo.Name
            ? NameUtil.Join(state.Target, state.Ext)
            : state.Target;

        return new PlanItem
        {
            Original = name,
            Proposed = proposed,
            Steps = trace,
            FullPath = file.FullName,
            Reason = string.Join("; ", context.Notes),
        };
    }

    /// <summary>Rule 7, first match wins: invalid → collision → unchanged → ok.</summary>
    private static void AssignStatuses(List<PlanItem> items)
    {
        var existing = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var item in items)
        {
            existing.Add(item.Original);
        }

        var proposedCounts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var item in items)
        {
            proposedCounts.TryGetValue(item.Proposed, out int count);
            proposedCounts[item.Proposed] = count + 1;
        }

        foreach (var item in items)
        {
            string notes = item.Reason;

            if (NameUtil.IsInvalid(item.Proposed, out string invalidReason))
            {
                Finish(item, ItemStatus.Invalid, invalidReason, notes);
                continue;
            }

            // "an existing file other than this item": names inside one folder are unique
            // case-insensitively, so matching the item's own original name means matching
            // itself, which the spec excludes.
            bool hitsExistingOther = existing.Contains(item.Proposed) &&
                !string.Equals(item.Proposed, item.Original, StringComparison.OrdinalIgnoreCase);

            bool hitsAnotherProposal = proposedCounts[item.Proposed] > 1;

            if (hitsExistingOther || hitsAnotherProposal)
            {
                string why = hitsExistingOther && hitsAnotherProposal
                    ? "another file already uses this name and another item proposes it too"
                    : hitsExistingOther
                        ? "another file in the folder already uses this name"
                        : "another item proposes the same name";
                Finish(item, ItemStatus.Collision, why, notes);
                continue;
            }

            if (string.Equals(item.Proposed, item.Original, StringComparison.Ordinal))
            {
                Finish(item, ItemStatus.Unchanged, "", notes);
                continue;
            }

            Finish(item, ItemStatus.Ok, "", notes);
        }
    }

    private static void Finish(PlanItem item, string status, string reason, string notes)
    {
        item.Status = status;
        if (reason.Length > 0 && notes.Length > 0)
        {
            item.Reason = reason + "; " + notes;
        }
        else
        {
            item.Reason = reason.Length > 0 ? reason : notes;
        }
    }
}

