using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;
using System.Text.Json.Nodes;

namespace BatchRenameStudio.Core;

/// <summary>
/// Serialises engine results into the two fixed wire contracts. Every document is built as an
/// ordered <see cref="JsonObject"/> so key order, indentation and line endings are fixed by us
/// rather than by the serialiser's defaults (spec rule 9: byte-identical output).
/// </summary>
public static class ReportWriter
{
    public const int SchemaVersion = 1;

    private static readonly JsonSerializerOptions WriteOptions = new()
    {
        WriteIndented = true,
        // Emit real UTF-8 for non-ASCII file names instead of \uXXXX escapes.
        Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
    };

    private static readonly UTF8Encoding Utf8NoBom = new(encoderShouldEmitUTF8Identifier: false);

    public static JsonObject BuildPlan(EngineResult result)
    {
        var items = new JsonArray();
        foreach (var item in result.Items)
        {
            items.Add(new JsonObject
            {
                ["original"] = item.Original,
                ["proposed"] = item.Proposed,
                ["status"] = item.Status,
                ["reason"] = item.Reason,
            });
        }

        return new JsonObject
        {
            ["schemaVersion"] = SchemaVersion,
            ["items"] = items,
            ["summary"] = new JsonObject
            {
                ["total"] = result.Summary.Total,
                ["ok"] = result.Summary.Ok,
                ["collision"] = result.Summary.Collision,
                ["unchanged"] = result.Summary.Unchanged,
                ["invalid"] = result.Summary.Invalid,
            },
        };
    }

    public static JsonObject BuildTrace(EngineResult result)
    {
        var files = new JsonArray();
        foreach (var item in result.Items)
        {
            var steps = new JsonArray();
            foreach (var step in item.Steps)
            {
                steps.Add(new JsonObject
                {
                    ["index"] = step.Index,
                    ["op"] = step.Op,
                    ["before"] = step.Before,
                    ["after"] = step.After,
                });
            }

            files.Add(new JsonObject
            {
                ["original"] = item.Original,
                ["steps"] = steps,
                ["proposed"] = item.Proposed,
                ["status"] = item.Status,
            });
        }

        return new JsonObject
        {
            ["schemaVersion"] = SchemaVersion,
            ["files"] = files,
        };
    }

    public static string Render(JsonNode node)
    {
        string text = node.ToJsonString(WriteOptions);
        // System.Text.Json indents with Environment.NewLine on .NET 8; normalise so the same
        // inputs give the same bytes on any host. Real CR/LF inside strings stay escaped.
        return text.Replace("\r\n", "\n") + "\n";
    }

    /// <summary>Writes UTF-8 without a BOM, creating the parent directory when needed.</summary>
    public static void WriteFile(string path, JsonNode node)
    {
        string full = Path.GetFullPath(path);
        string? parent = Path.GetDirectoryName(full);
        if (!string.IsNullOrEmpty(parent))
        {
            Directory.CreateDirectory(parent);
        }

        File.WriteAllText(full, Render(node), Utf8NoBom);
    }

    public static void WriteText(string path, string text)
    {
        string full = Path.GetFullPath(path);
        string? parent = Path.GetDirectoryName(full);
        if (!string.IsNullOrEmpty(parent))
        {
            Directory.CreateDirectory(parent);
        }

        File.WriteAllText(full, text, Utf8NoBom);
    }
}

