using System.Globalization;
using System.Text.Json.Nodes;

namespace BatchRenameStudio.Core;

public sealed record RenameAction(string From, string To);

/// <summary>One applied rename batch; the unit of undo.</summary>
public sealed class UndoBatch
{
    public required string Id { get; init; }

    public required string TimestampUtc { get; init; }

    public required string Directory { get; init; }

    public required List<RenameAction> Actions { get; init; }

    public JsonObject ToJson()
    {
        var actions = new JsonArray();
        foreach (var action in Actions)
        {
            actions.Add(new JsonObject { ["from"] = action.From, ["to"] = action.To });
        }

        return new JsonObject
        {
            ["schemaVersion"] = 1,
            ["id"] = Id,
            ["timestampUtc"] = TimestampUtc,
            ["directory"] = Directory,
            ["actions"] = actions,
        };
    }

    public string Describe() =>
        $"{TimestampUtc}  {Actions.Count} file(s)  {Directory}";
}

public sealed class ApplyOutcome
{
    public int Renamed { get; set; }

    public List<string> Errors { get; } = new();

    public UndoBatch? Batch { get; set; }

    public bool RolledBack { get; set; }

    public bool Success => Errors.Count == 0;
}

/// <summary>
/// Performs renames through a temporary staging pass so that swaps (a↔b), case-only changes and
/// chains (a→b→c) all succeed, and so a mid-way failure can be rolled back completely.
/// </summary>
public static class RenameApplier
{
    public static string UndoDirectory => Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
        "BatchRenameStudio",
        "undo");

    public static ApplyOutcome Apply(string directory, IReadOnlyList<PlanItem> items)
    {
        var pairs = items
            .Where(i => i.Status == ItemStatus.Ok)
            .Select(i => new RenameAction(i.Original, i.Proposed))
            .ToList();

        var outcome = Move(directory, pairs);
        if (outcome.Renamed > 0)
        {
            var batch = new UndoBatch
            {
                Id = Guid.NewGuid().ToString("N"),
                TimestampUtc = DateTime.UtcNow.ToString("yyyy-MM-dd HH:mm:ss'Z'", CultureInfo.InvariantCulture),
                Directory = directory,
                Actions = pairs,
            };
            outcome.Batch = batch;
            TryPersist(batch, outcome);
        }

        return outcome;
    }

    public static ApplyOutcome Undo(UndoBatch batch)
    {
        var reversed = batch.Actions
            .Select(a => new RenameAction(a.To, a.From))
            .Reverse()
            .ToList();

        return Move(batch.Directory, reversed);
    }

    private static ApplyOutcome Move(string directory, IReadOnlyList<RenameAction> pairs)
    {
        var outcome = new ApplyOutcome();
        if (pairs.Count == 0)
        {
            return outcome;
        }

        var staged = new List<(string Temp, string Target, string Original)>(pairs.Count);

        try
        {
            // Phase 1: park every source under a name nothing else can claim.
            for (int i = 0; i < pairs.Count; i++)
            {
                string source = Path.Combine(directory, pairs[i].From);
                if (!File.Exists(source))
                {
                    throw new FileNotFoundException($"'{pairs[i].From}' is no longer in the folder.", source);
                }

                string temp = ReserveTempPath(directory, i);
                File.Move(source, temp);
                staged.Add((temp, Path.Combine(directory, pairs[i].To), pairs[i].From));
            }

            // Phase 2: land them on the requested names.
            for (int i = 0; i < staged.Count; i++)
            {
                var entry = staged[i];
                if (File.Exists(entry.Target) || Directory.Exists(entry.Target))
                {
                    throw new IOException($"'{Path.GetFileName(entry.Target)}' appeared in the folder during the rename.");
                }

                File.Move(entry.Temp, entry.Target);
                staged[i] = (entry.Target, entry.Target, entry.Original);
                outcome.Renamed++;
            }
        }
        catch (Exception ex)
        {
            outcome.Errors.Add(ex.Message);
            RollBack(directory, staged, outcome);
            outcome.Renamed = 0;
        }

        return outcome;
    }

    private static void RollBack(
        string directory,
        List<(string Temp, string Target, string Original)> staged,
        ApplyOutcome outcome)
    {
        outcome.RolledBack = true;
        for (int i = staged.Count - 1; i >= 0; i--)
        {
            var entry = staged[i];
            string back = Path.Combine(directory, entry.Original);
            try
            {
                if (File.Exists(entry.Temp) && !File.Exists(back))
                {
                    File.Move(entry.Temp, back);
                }
            }
            catch (Exception ex)
            {
                outcome.RolledBack = false;
                outcome.Errors.Add($"rollback of '{entry.Original}' failed: {ex.Message}");
            }
        }
    }

    private static string ReserveTempPath(string directory, int index)
    {
        for (int attempt = 0; attempt < 1000; attempt++)
        {
            string candidate = Path.Combine(
                directory,
                string.Format(CultureInfo.InvariantCulture, "~brs-{0}-{1}.tmp", index, attempt));
            if (!File.Exists(candidate) && !Directory.Exists(candidate))
            {
                return candidate;
            }
        }

        throw new IOException("Could not reserve a staging name in the target folder.");
    }

    private static void TryPersist(UndoBatch batch, ApplyOutcome outcome)
    {
        try
        {
            Directory.CreateDirectory(UndoDirectory);
            string file = Path.Combine(UndoDirectory, $"{batch.TimestampUtc.Replace(':', '-').Replace(' ', '_')}-{batch.Id[..8]}.json");
            ReportWriter.WriteFile(file, batch.ToJson());
        }
        catch (Exception ex)
        {
            // Losing the on-disk journal must never fail a rename that already succeeded.
            outcome.Errors.Add($"undo journal not written: {ex.Message}");
        }
    }
}

