using System.Globalization;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

public static class ExitCodes
{
    public const int Success = 0;
    public const int RuntimeError = 1;
    public const int UsageError = 2;
}

/// <summary>
/// Implements the two fixed headless contracts. Neither of them touches the file system apart
/// from reading the folder listing and writing the requested report.
/// </summary>
public static class HeadlessRunner
{
    public const string UsageText = """
        Batch Rename Studio Pro

          BatchRenameStudio.exe
              Launch the graphical rule editor.

          BatchRenameStudio.exe --plan    --dir <folder> --rules <rules.json> --out <plan.json>
              Write the rename plan. Renames nothing.

          BatchRenameStudio.exe --explain --dir <folder> --rules <rules.json> --out <trace.json>
              Write the per-step trace. Renames nothing.

          BatchRenameStudio.exe --help | --version

        Exit codes: 0 success, 1 runtime error, 2 usage error.
        """;

    public static int Run(string[] args)
    {
        var stdout = Console.Out;
        var stderr = Console.Error;

        try
        {
            if (args.Any(a => a is "--help" or "-h" or "/?"))
            {
                stderr.WriteLine(UsageText);
                return ExitCodes.Success;
            }

