using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// Renders the parameter form for whichever step is selected. The form is generated from the
/// [StepField] metadata, so adding an operation never means touching the GUI.
/// </summary>
public sealed class StepEditorPanel : Panel
{
    private RuleStep? _step;
    private bool _loading;

    public StepEditorPanel()
    {
        AutoScroll = true;
        Padding = new Padding(10);
        BackColor = SystemColors.Window;
    }

    /// <summary>Raised whenever the user edits a parameter of the current step.</summary>
    public event EventHandler? StepChanged;

    public void Bind(RuleStep? step)
    {
        _step = step;
        Rebuild();
    }

    private void Rebuild()
    {
        SuspendLayout();
        while (Controls.Count > 0)
        {
            var old = Controls[0];
            Controls.RemoveAt(0);
            old.Dispose();
        }

        if (_step is null)
        {
            Controls.Add(new Label
            {
                Text = "Select a rule on the left to edit its parameters,\r\nor add one with the picker above.",
                AutoSize = true,
                ForeColor = SystemColors.GrayText,
            });
            ResumeLayout();
            return;
        }

        var meta = StepRegistry.MetaOf(_step);

        var table = new TableLayoutPanel
        {
            Dock = DockStyle.Top,
            AutoSize = true,
            AutoSizeMode = AutoSizeMode.GrowAndShrink,
            ColumnCount = 2,
            GrowStyle = TableLayoutPanelGrowStyle.AddRows,
        };
        table.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        table.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100F));

        var title = new Label
        {
            Text = meta?.Display ?? _step.OpName,
            AutoSize = true,
            Font = new Font(Font, FontStyle.Bold),
            Margin = new Padding(0, 0, 0, 2),
        };
        table.Controls.Add(title);
        table.SetColumnSpan(title, 2);

        var description = new Label
        {
            Text = meta?.Description.Length > 0 ? meta.Description : $"op: {_step.OpName}",
            AutoSize = true,
            MaximumSize = new Size(560, 0),
            ForeColor = SystemColors.GrayText,
            Margin = new Padding(0, 0, 0, 10),
        };
        table.Controls.Add(description);
        table.SetColumnSpan(description, 2);

        if (meta is null || meta.Fields.Count == 0)
        {
            var none = new Label
            {
                Text = meta is null
                    ? "This operation came from the rules file and is not editable here."
                    : "This operation takes no parameters.",
                AutoSize = true,
                ForeColor = SystemColors.GrayText,
            };
            table.Controls.Add(none);
            table.SetColumnSpan(none, 2);
        }
        else
        {
            _loading = true;
            foreach (var field in meta.Fields)
            {
                table.Controls.Add(new Label
                {
                    Text = field.Label,
                    AutoSize = true,
                    Anchor = AnchorStyles.Left,
                    Margin = new Padding(0, 6, 10, 3),
                });

                table.Controls.Add(BuildEditor(field));

                if (field.Hint.Length > 0)
                {
                    table.Controls.Add(new Label { Text = "", AutoSize = true, Width = 0 });
                    table.Controls.Add(new Label
                    {
                        Text = field.Hint,
                        AutoSize = true,
                        MaximumSize = new Size(440, 0),
                        ForeColor = SystemColors.GrayText,
                        Margin = new Padding(0, 0, 0, 8),
                    });
                }
            }

            _loading = false;
        }

        Controls.Add(table);
        ResumeLayout();
    }

    private Control BuildEditor(StepFieldMeta field)
    {
        var step = _step!;

        if (field.Type == typeof(bool))
        {
            var check = new CheckBox
            {
                Checked = (bool)(field.Get(step) ?? false),
                AutoSize = true,
                Anchor = AnchorStyles.Left,
                Margin = new Padding(0, 5, 0, 3),
            };
            check.CheckedChanged += (_, _) =>
            {
                if (_loading) return;
                field.Set(step, check.Checked);
                Notify();
            };
            return check;
        }

        if (field.Type == typeof(int))
        {
            var spin = new NumericUpDown
            {
                Minimum = -1_000_000,
                Maximum = 1_000_000,
                Width = 120,
                Anchor = AnchorStyles.Left,
                Margin = new Padding(0, 3, 0, 3),
                Value = Clamp((int)(field.Get(step) ?? 0)),
            };
            spin.ValueChanged += (_, _) =>
            {
                if (_loading) return;
                field.Set(step, (int)spin.Value);
                Notify();
            };
            return spin;
        }

        string current = (string?)field.Get(step) ?? "";

        if (field.Choices.Length > 0)
        {
            var combo = new ComboBox
            {
                DropDownStyle = ComboBoxStyle.DropDownList,
                Width = 200,
                Anchor = AnchorStyles.Left,
                Margin = new Padding(0, 3, 0, 3),
            };
            combo.Items.AddRange(field.Choices);
            int index = Array.FindIndex(field.Choices, c => string.Equals(c, current, StringComparison.Ordinal));
            combo.SelectedIndex = index >= 0 ? index : 0;
            combo.SelectedIndexChanged += (_, _) =>
            {
                if (_loading) return;
                field.Set(step, (string)combo.Items[combo.SelectedIndex]!);
                Notify();
            };
            return combo;
        }

        var box = new TextBox
        {
            Text = current,
            Dock = DockStyle.Fill,
            Margin = new Padding(0, 3, 6, 3),
        };
        box.TextChanged += (_, _) =>
        {
            if (_loading) return;
            field.Set(step, box.Text);
            Notify();
        };
        return box;
    }

    private static decimal Clamp(int value) => Math.Clamp(value, -1_000_000, 1_000_000);

    private void Notify() => StepChanged?.Invoke(this, EventArgs.Empty);
}

