using System.Globalization;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

public sealed class MainForm : Form
{
    private readonly RuleSet _rules = new();
    private readonly Stack<UndoBatch> _undoStack = new();
    private readonly System.Windows.Forms.Timer _debounce;

    private EngineResult? _result;
    private bool _suspendEvents;

    private readonly TextBox _txtFolder = new();
    private readonly ComboBox _cboApplyTo = new();
    private readonly ComboBox _cboSort = new();
    private readonly ComboBox _cboNewOp = new();
    private readonly ListView _lstRules = new();
    private readonly StepEditorPanel _editor = new();
    private readonly DataGridView _gridPreview = new();
    private readonly DataGridView _gridTrace = new();
    private readonly Label _lblTraceHeader = new();
    private readonly Label _lblStatus = new();
    private readonly Button _btnApply = new();
    private readonly Button _btnUndo = new();

    public MainForm()
    {
        Text = "Batch Rename Studio Pro";
        MinimumSize = new Size(1000, 660);
        Size = new Size(1280, 840);
        StartPosition = FormStartPosition.CenterScreen;
        Font = new Font("Segoe UI", 9F);
        AllowDrop = true;

        _debounce = new System.Windows.Forms.Timer { Interval = 200 };
        _debounce.Tick += (_, _) => Recompute();

        Controls.Add(BuildLayout());

        DragEnter += OnDragEnter;
        DragDrop += OnDragDrop;
        Load += (_, _) =>
        {
            _txtFolder.Text = Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments);
            RefreshRuleList();
            Recompute();
        };
    }

    // ------------------------------------------------------------------ layout

    private Control BuildLayout()
    {
        var root = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 1,
            RowCount = 3,
            Padding = new Padding(8),
        };
        root.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        root.RowStyles.Add(new RowStyle(SizeType.Percent, 100F));
        root.RowStyles.Add(new RowStyle(SizeType.AutoSize));

        root.Controls.Add(BuildHeader(), 0, 0);
        root.Controls.Add(BuildBody(), 0, 1);
        root.Controls.Add(BuildFooter(), 0, 2);
        return root;
    }

    private Control BuildHeader()
    {
        var host = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            AutoSize = true,
            AutoSizeMode = AutoSizeMode.GrowAndShrink,
            ColumnCount = 1,
            RowCount = 2,
        };

        var row1 = NewFlowRow();
        row1.Controls.Add(NewLabel("Folder", bold: true));
        _txtFolder.Width = 620;
        _txtFolder.Margin = new Padding(0, 2, 6, 2);
        _txtFolder.TextChanged += (_, _) => QueueRecompute();
        row1.Controls.Add(_txtFolder);
        row1.Controls.Add(NewButton("Browse…", 90, OnBrowse));
        row1.Controls.Add(NewButton("Refresh", 80, (_, _) => Recompute()));
        row1.Controls.Add(NewLabel("   (or drop a folder anywhere on this window)"));

        var row2 = NewFlowRow();
        row2.Controls.Add(NewLabel("Apply to"));
        _cboApplyTo.DropDownStyle = ComboBoxStyle.DropDownList;
        _cboApplyTo.Width = 170;
        _cboApplyTo.Margin = new Padding(0, 2, 14, 2);
        _cboApplyTo.Items.AddRange(new object[] { "name", "nameAndExtension" });
        _cboApplyTo.SelectedIndex = 0;
        _cboApplyTo.SelectedIndexChanged += (_, _) =>
        {
            _rules.ApplyTo = NameUtil.ParseApplyTo((string)_cboApplyTo.SelectedItem!);
            QueueRecompute();
        };
        row2.Controls.Add(_cboApplyTo);

        row2.Controls.Add(NewLabel("Sort by"));
        _cboSort.DropDownStyle = ComboBoxStyle.DropDownList;
        _cboSort.Width = 130;
        _cboSort.Margin = new Padding(0, 2, 24, 2);
        _cboSort.Items.AddRange(new object[] { "name", "created", "modified" });
        _cboSort.SelectedIndex = 0;
        _cboSort.SelectedIndexChanged += (_, _) =>
        {
            _rules.Sort = RuleSet.ParseSort((string)_cboSort.SelectedItem!);
            QueueRecompute();
        };
        row2.Controls.Add(_cboSort);

        row2.Controls.Add(NewButton("Load rules…", 100, OnLoadRules));
        row2.Controls.Add(NewButton("Save rules…", 100, OnSaveRules));
        row2.Controls.Add(NewButton("Export plan…", 110, OnExportPlan));
        row2.Controls.Add(NewButton("Export trace…", 110, OnExportTrace));

        host.Controls.Add(row1, 0, 0);
        host.Controls.Add(row2, 0, 1);
        return host;
    }

    private Control BuildBody()
    {
        var outer = new SplitContainer
        {
            Dock = DockStyle.Fill,
            Orientation = Orientation.Horizontal,
            Panel1MinSize = 160,
            Panel2MinSize = 200,
        };
        outer.Panel1.Controls.Add(BuildRulesArea());
        outer.Panel2.Controls.Add(BuildPreviewArea());
        outer.HandleCreated += (_, _) => SafeSplit(outer, 310);
        return outer;
    }

    private Control BuildRulesArea()
    {
        var split = new SplitContainer
        {
            Dock = DockStyle.Fill,
            Orientation = Orientation.Vertical,
            Panel1MinSize = 260,
            Panel2MinSize = 260,
        };
        split.HandleCreated += (_, _) => SafeSplit(split, 620);

        // --- left: the ordered rule list plus its toolbar
        var left = NewSection("Rules  (applied top to bottom)");

        var tools = NewFlowRow();
        _cboNewOp.DropDownStyle = ComboBoxStyle.DropDownList;
        _cboNewOp.Width = 200;
        _cboNewOp.Margin = new Padding(0, 2, 6, 4);
        foreach (var meta in StepRegistry.All)
        {
            _cboNewOp.Items.Add($"{meta.Display}  ({meta.Op})");
        }

        _cboNewOp.SelectedIndex = 0;
        tools.Controls.Add(_cboNewOp);
        tools.Controls.Add(NewButton("Add", 60, (_, _) => AddSelectedOp()));
        tools.Controls.Add(NewButton("Duplicate", 80, (_, _) => DuplicateStep()));
        tools.Controls.Add(NewButton("Remove", 70, (_, _) => RemoveStep()));
        tools.Controls.Add(NewButton("Up", 46, (_, _) => MoveStep(-1)));
        tools.Controls.Add(NewButton("Down", 56, (_, _) => MoveStep(+1)));
        tools.Controls.Add(NewButton("Clear", 60, (_, _) => ClearSteps()));

        _lstRules.Dock = DockStyle.Fill;
        _lstRules.View = View.Details;
        _lstRules.FullRowSelect = true;
        _lstRules.MultiSelect = false;
        _lstRules.HideSelection = false;
        _lstRules.Columns.Add("#", 34);
        _lstRules.Columns.Add("Operation", 130);
        _lstRules.Columns.Add("Parameters", 380);
        _lstRules.SelectedIndexChanged += (_, _) =>
        {
            if (_suspendEvents) return;
            _editor.Bind(SelectedStep());
        };

        left.Controls.Add(tools, 0, 1);
        left.Controls.Add(_lstRules, 0, 2);

        // --- right: the parameter form for the selected rule
        var right = NewSection("Parameters");
        _editor.Dock = DockStyle.Fill;
        _editor.StepChanged += (_, _) =>
        {
            RefreshRuleListTextOnly();
            QueueRecompute();
        };
        right.Controls.Add(_editor, 0, 1);
        right.SetRowSpan(_editor, 2);

        split.Panel1.Controls.Add(left);
        split.Panel2.Controls.Add(right);
        return split;
    }

    private Control BuildPreviewArea()
    {
        var split = new SplitContainer
        {
            Dock = DockStyle.Fill,
            Orientation = Orientation.Vertical,
            Panel1MinSize = 320,
            Panel2MinSize = 260,
        };
        split.HandleCreated += (_, _) => SafeSplit(split, 700);

        var previewSection = NewSection("Preview");
        ConfigureGrid(_gridPreview);
        _gridPreview.Columns.Add(NewColumn("Original", 34));
        _gridPreview.Columns.Add(NewColumn("Proposed", 34));
        _gridPreview.Columns.Add(NewColumn("Status", 12));
        _gridPreview.Columns.Add(NewColumn("Reason", 20));
        _gridPreview.SelectionChanged += (_, _) => ShowTraceForSelection();
        previewSection.Controls.Add(_gridPreview, 0, 1);
        previewSection.SetRowSpan(_gridPreview, 2);

        var traceSection = NewSection("Step trace");
        _lblTraceHeader.Text = "Select a file above to see how each step transformed it.";
        _lblTraceHeader.AutoSize = true;
        _lblTraceHeader.ForeColor = SystemColors.GrayText;
        _lblTraceHeader.Margin = new Padding(0, 0, 0, 4);
        ConfigureGrid(_gridTrace);
        _gridTrace.Columns.Add(NewColumn("#", 8));
        _gridTrace.Columns.Add(NewColumn("Operation", 24));
        _gridTrace.Columns.Add(NewColumn("Before", 34));
        _gridTrace.Columns.Add(NewColumn("After", 34));
        traceSection.Controls.Add(_lblTraceHeader, 0, 1);
        traceSection.Controls.Add(_gridTrace, 0, 2);

        split.Panel1.Controls.Add(previewSection);
        split.Panel2.Controls.Add(traceSection);
        return split;
    }

    private Control BuildFooter()
    {
        var row = NewFlowRow();

        _btnApply.Text = "Apply rename";
        _btnApply.Width = 130;
        _btnApply.Height = 30;
        _btnApply.Margin = new Padding(0, 6, 8, 0);
        _btnApply.Click += OnApply;
        row.Controls.Add(_btnApply);

        _btnUndo.Text = "Undo last";
        _btnUndo.Width = 110;
        _btnUndo.Height = 30;
        _btnUndo.Margin = new Padding(0, 6, 20, 0);
        _btnUndo.Enabled = false;
        _btnUndo.Click += OnUndo;
        row.Controls.Add(_btnUndo);

        _lblStatus.AutoSize = true;
        _lblStatus.Margin = new Padding(0, 13, 0, 0);
        _lblStatus.Text = "Ready.";
        row.Controls.Add(_lblStatus);

        return row;
    }

    // ------------------------------------------------------------- small helpers

    private static FlowLayoutPanel NewFlowRow() => new()
    {
        Dock = DockStyle.Fill,
        AutoSize = true,
        AutoSizeMode = AutoSizeMode.GrowAndShrink,
        WrapContents = false,
        FlowDirection = FlowDirection.LeftToRight,
        Margin = new Padding(0, 2, 0, 2),
    };

    private static Label NewLabel(string text, bool bold = false)
    {
        var label = new Label
        {
            Text = text,
            AutoSize = true,
            Margin = new Padding(0, 6, 8, 0),
        };
        if (bold)
        {
            label.Font = new Font(label.Font, FontStyle.Bold);
        }

        return label;
    }

    private static Button NewButton(string text, int width, EventHandler onClick)
    {
        var button = new Button
        {
            Text = text,
            Width = width,
            Margin = new Padding(0, 1, 6, 1),
        };
        button.Click += onClick;
        return button;
    }

    /// <summary>A titled container: row 0 is the caption, the caller fills rows 1 and 2.</summary>
    private static TableLayoutPanel NewSection(string caption)
    {
        var panel = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 1,
            RowCount = 3,
            Padding = new Padding(6, 2, 6, 4),
        };
        panel.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        panel.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        panel.RowStyles.Add(new RowStyle(SizeType.Percent, 100F));

        var title = new Label
        {
            Text = caption,
            AutoSize = true,
            Font = new Font(SystemFonts.DefaultFont, FontStyle.Bold),
            Margin = new Padding(0, 0, 0, 4),
        };
        panel.Controls.Add(title, 0, 0);
        return panel;
    }

    private static void ConfigureGrid(DataGridView grid)
    {
        grid.Dock = DockStyle.Fill;
        grid.ReadOnly = true;
        grid.AllowUserToAddRows = false;
        grid.AllowUserToDeleteRows = false;
        grid.AllowUserToResizeRows = false;
        grid.RowHeadersVisible = false;
        grid.SelectionMode = DataGridViewSelectionMode.FullRowSelect;
        grid.MultiSelect = false;
        grid.AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.Fill;
        grid.BackgroundColor = SystemColors.Window;
        grid.BorderStyle = BorderStyle.FixedSingle;
        grid.EnableHeadersVisualStyles = false;
        grid.ColumnHeadersDefaultCellStyle.BackColor = SystemColors.Control;
        grid.ColumnHeadersDefaultCellStyle.Font = new Font(SystemFonts.DefaultFont, FontStyle.Bold);
        grid.DefaultCellStyle.SelectionBackColor = SystemColors.Highlight;
    }

    private static DataGridViewTextBoxColumn NewColumn(string header, int weight) => new()
    {
        HeaderText = header,
        FillWeight = weight,
        SortMode = DataGridViewColumnSortMode.NotSortable,
    };

    private static void SafeSplit(SplitContainer container, int distance)
    {
        try
        {
            int span = container.Orientation == Orientation.Horizontal ? container.Height : container.Width;
            int min = container.Panel1MinSize;
            int max = span - container.Panel2MinSize - container.SplitterWidth;
            if (max > min)
            {
                container.SplitterDistance = Math.Clamp(distance, min, max);
            }
        }
        catch (InvalidOperationException)
        {
            // The container is too small to honour the request; the default split is fine.
        }
    }

    private RuleStep? SelectedStep()
    {
        int index = SelectedRuleIndex();
        return index >= 0 && index < _rules.Steps.Count ? _rules.Steps[index] : null;
    }

    private int SelectedRuleIndex() =>
        _lstRules.SelectedIndices.Count > 0 ? _lstRules.SelectedIndices[0] : -1;

    // ------------------------------------------------------------- rule editing

    private void AddSelectedOp()
    {
        var meta = StepRegistry.All[Math.Max(0, _cboNewOp.SelectedIndex)];
        _rules.Steps.Add(meta.Create());
        RefreshRuleList(_rules.Steps.Count - 1);
        QueueRecompute();
    }

    private void DuplicateStep()
    {
        int index = SelectedRuleIndex();
        if (index < 0) return;
        _rules.Steps.Insert(index + 1, _rules.Steps[index].Clone());
        RefreshRuleList(index + 1);
        QueueRecompute();
    }

    private void RemoveStep()
    {
        int index = SelectedRuleIndex();
        if (index < 0) return;
        _rules.Steps.RemoveAt(index);
        RefreshRuleList(Math.Min(index, _rules.Steps.Count - 1));
        QueueRecompute();
    }

    private void MoveStep(int delta)
    {
        int index = SelectedRuleIndex();
        int target = index + delta;
        if (index < 0 || target < 0 || target >= _rules.Steps.Count) return;
        (_rules.Steps[index], _rules.Steps[target]) = (_rules.Steps[target], _rules.Steps[index]);
        RefreshRuleList(target);
        QueueRecompute();
    }

    private void ClearSteps()
    {
        if (_rules.Steps.Count == 0) return;
        if (MessageBox.Show(this, "Remove every rule?", "Batch Rename Studio Pro",
                MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes)
        {
            return;
        }

        _rules.Steps.Clear();
        RefreshRuleList();
        QueueRecompute();
    }

    private void RefreshRuleList(int select = -1)
    {
        _suspendEvents = true;
        _lstRules.BeginUpdate();
        _lstRules.Items.Clear();
        for (int i = 0; i < _rules.Steps.Count; i++)
        {
            var step = _rules.Steps[i];
            var meta = StepRegistry.MetaOf(step);
            var row = new ListViewItem((i + 1).ToString(CultureInfo.InvariantCulture));
            row.SubItems.Add(meta?.Display ?? step.OpName);
            row.SubItems.Add(step.Summary());
            _lstRules.Items.Add(row);
        }

        _lstRules.EndUpdate();
        _suspendEvents = false;

        if (select >= 0 && select < _lstRules.Items.Count)
        {
            _lstRules.Items[select].Selected = true;
            _lstRules.Items[select].Focused = true;
            _lstRules.EnsureVisible(select);
        }

        _editor.Bind(SelectedStep());
    }

    /// <summary>Updates the summary column without rebuilding the parameter form.</summary>
    private void RefreshRuleListTextOnly()
    {
        for (int i = 0; i < _lstRules.Items.Count && i < _rules.Steps.Count; i++)
        {
            _lstRules.Items[i].SubItems[2].Text = _rules.Steps[i].Summary();
        }
    }

    // ------------------------------------------------------------ preview + trace

    private void QueueRecompute()
    {
        _debounce.Stop();
        _debounce.Start();
    }

    private void Recompute()
    {
        _debounce.Stop();
        string dir = _txtFolder.Text.Trim().Trim('"');

        if (dir.Length == 0 || !Directory.Exists(dir))
        {
            _result = null;
            _gridPreview.Rows.Clear();
            _gridTrace.Rows.Clear();
            SetStatus(dir.Length == 0 ? "Pick a folder to begin." : $"Folder not found: {dir}", warn: true);
            _btnApply.Enabled = false;
            return;
        }

        try
        {
            _result = RenameEngine.Run(dir, _rules);
        }
        catch (Exception ex)
        {
            _result = null;
            _gridPreview.Rows.Clear();
            _gridTrace.Rows.Clear();
            SetStatus($"Could not read the folder: {ex.Message}", warn: true);
            _btnApply.Enabled = false;
            return;
        }

        int keepRow = _gridPreview.CurrentCell?.RowIndex ?? -1;

        _gridPreview.SuspendLayout();
        _gridPreview.Rows.Clear();
        foreach (var item in _result.Items)
        {
            int rowIndex = _gridPreview.Rows.Add(item.Original, item.Proposed, item.Status, item.Reason);
            var row = _gridPreview.Rows[rowIndex];
            row.Tag = item;
            switch (item.Status)
            {
                case ItemStatus.Ok:
                    row.DefaultCellStyle.BackColor = Color.FromArgb(232, 246, 232);
                    break;
                case ItemStatus.Collision:
                    row.DefaultCellStyle.BackColor = Color.FromArgb(255, 240, 214);
                    break;
                case ItemStatus.Invalid:
                    row.DefaultCellStyle.BackColor = Color.FromArgb(255, 226, 226);
                    break;
                default:
                    row.DefaultCellStyle.ForeColor = SystemColors.GrayText;
                    break;
            }
        }

        _gridPreview.ResumeLayout();

        if (keepRow >= 0 && keepRow < _gridPreview.Rows.Count)
        {
            _gridPreview.CurrentCell = _gridPreview.Rows[keepRow].Cells[0];
        }

        var s = _result.Summary;
        _btnApply.Enabled = s.Ok > 0;
        SetStatus(string.Format(
            CultureInfo.InvariantCulture,
            "{0} file(s):  ok {1}   collision {2}   unchanged {3}   invalid {4}   |   {5} rule(s)",
            s.Total, s.Ok, s.Collision, s.Unchanged, s.Invalid, _rules.Steps.Count));

        ShowTraceForSelection();
    }

    private void ShowTraceForSelection()
    {
        _gridTrace.Rows.Clear();

        var row = _gridPreview.CurrentRow;
        if (row?.Tag is not PlanItem item)
        {
            _lblTraceHeader.Text = "Select a file above to see how each step transformed it.";
            return;
        }

        _lblTraceHeader.Text = $"{item.Original}  →  {item.Proposed}   [{item.Status}]" +
                               (item.Reason.Length > 0 ? $"   — {item.Reason}" : "");

        foreach (var step in item.Steps)
        {
            int index = _gridTrace.Rows.Add(
                step.Index.ToString(CultureInfo.InvariantCulture), step.Op, step.Before, step.After);
            if (!step.Changed)
            {
                _gridTrace.Rows[index].DefaultCellStyle.ForeColor = SystemColors.GrayText;
            }
        }
    }

    private void SetStatus(string text, bool warn = false)
    {
        _lblStatus.Text = text;
        _lblStatus.ForeColor = warn ? Color.FromArgb(168, 40, 40) : SystemColors.ControlText;
    }

    // ------------------------------------------------------------------ commands

    private void OnBrowse(object? sender, EventArgs e)
    {
        using var dialog = new FolderBrowserDialog { Description = "Choose the folder to rename in." };
        if (Directory.Exists(_txtFolder.Text))
        {
            dialog.SelectedPath = _txtFolder.Text;
        }

        if (dialog.ShowDialog(this) == DialogResult.OK)
        {
            _txtFolder.Text = dialog.SelectedPath;
            Recompute();
        }
    }

    private void OnLoadRules(object? sender, EventArgs e)
    {
        using var dialog = new OpenFileDialog
        {
            Title = "Load rules",
            Filter = "Rule sets (*.json)|*.json|All files (*.*)|*.*",
        };
        if (dialog.ShowDialog(this) != DialogResult.OK) return;

        try
        {
            var loaded = StepJson.LoadRuleSet(dialog.FileName);
            _rules.ApplyTo = loaded.ApplyTo;
            _rules.Sort = loaded.Sort;
            _rules.Steps.Clear();
            _rules.Steps.AddRange(loaded.Steps);

            _cboApplyTo.SelectedItem = NameUtil.ApplyToWire(_rules.ApplyTo);
            _cboSort.SelectedItem = RuleSet.SortWire(_rules.Sort);
            RefreshRuleList(_rules.Steps.Count > 0 ? 0 : -1);
            Recompute();
        }
        catch (Exception ex)
        {
            Error("Could not load that rule set.", ex);
        }
    }

    private void OnSaveRules(object? sender, EventArgs e)
    {
        using var dialog = new SaveFileDialog
        {
            Title = "Save rules",
            Filter = "Rule sets (*.json)|*.json",
            FileName = "rules.json",
        };
        if (dialog.ShowDialog(this) != DialogResult.OK) return;

        try
        {
            ReportWriter.WriteFile(dialog.FileName, StepJson.ToJson(_rules));
            SetStatus($"Rules saved to {dialog.FileName}");
        }
        catch (Exception ex)
        {
            Error("Could not save the rule set.", ex);
        }
    }

    private void OnExportPlan(object? sender, EventArgs e) =>
        Export("plan.json", "Export plan", r => ReportWriter.BuildPlan(r));

    private void OnExportTrace(object? sender, EventArgs e) =>
        Export("trace.json", "Export trace", r => ReportWriter.BuildTrace(r));

    private void Export(string defaultName, string title, Func<EngineResult, System.Text.Json.Nodes.JsonObject> build)
    {
        if (_result is null)
        {
            Error("There is nothing to export yet — choose a folder first.", null);
            return;
        }

        using var dialog = new SaveFileDialog
        {
            Title = title,
            Filter = "JSON (*.json)|*.json",
            FileName = defaultName,
        };
        if (dialog.ShowDialog(this) != DialogResult.OK) return;

        try
        {
            ReportWriter.WriteFile(dialog.FileName, build(_result));
            SetStatus($"Written to {dialog.FileName}");
        }
        catch (Exception ex)
        {
            Error("Could not write that file.", ex);
        }
    }

    private void OnApply(object? sender, EventArgs e)
    {
        if (_result is null) return;

        var ready = _result.Items.Where(i => i.Status == ItemStatus.Ok).ToList();
        if (ready.Count == 0)
        {
            Error("No file is in the 'ok' state, so there is nothing to rename.", null);
            return;
        }

        var s = _result.Summary;
        string question =
            $"Rename {ready.Count} file(s) in\r\n{_result.Directory}\r\n\r\n" +
            $"Skipped: {s.Unchanged} unchanged, {s.Collision} collision, {s.Invalid} invalid.\r\n\r\nProceed?";
        if (MessageBox.Show(this, question, "Confirm rename", MessageBoxButtons.OKCancel, MessageBoxIcon.Warning)
            != DialogResult.OK)
        {
            return;
        }

        Cursor = Cursors.WaitCursor;
        ApplyOutcome outcome;
        try
        {
            outcome = RenameApplier.Apply(_result.Directory, _result.Items);
        }
        finally
        {
            Cursor = Cursors.Default;
        }

        if (outcome.Batch is not null && outcome.Renamed > 0)
        {
            _undoStack.Push(outcome.Batch);
            _btnUndo.Enabled = true;
        }

        if (outcome.Errors.Count > 0)
        {
            string detail = string.Join("\r\n", outcome.Errors);
            string prefix = outcome.Renamed == 0
                ? (outcome.RolledBack
                    ? "The rename failed and every file was put back."
                    : "The rename failed and could NOT be fully rolled back — check the folder.")
                : $"{outcome.Renamed} file(s) were renamed, with warnings.";
            MessageBox.Show(this, prefix + "\r\n\r\n" + detail, "Rename",
                MessageBoxButtons.OK, outcome.Renamed == 0 ? MessageBoxIcon.Error : MessageBoxIcon.Warning);
        }
        else
        {
            SetStatus($"Renamed {outcome.Renamed} file(s). Undo is available.");
        }

        Recompute();
    }

    private void OnUndo(object? sender, EventArgs e)
    {
        if (_undoStack.Count == 0) return;

        var batch = _undoStack.Peek();
        if (MessageBox.Show(this, $"Undo this batch?\r\n\r\n{batch.Describe()}", "Undo",
                MessageBoxButtons.OKCancel, MessageBoxIcon.Question) != DialogResult.OK)
        {
            return;
        }

        var outcome = RenameApplier.Undo(batch);
        if (outcome.Errors.Count > 0)
        {
            MessageBox.Show(this, string.Join("\r\n", outcome.Errors), "Undo",
                MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
        else
        {
            _undoStack.Pop();
            SetStatus($"Undone: {outcome.Renamed} file(s) restored.");
        }

        _btnUndo.Enabled = _undoStack.Count > 0;
        Recompute();
    }

    private void Error(string message, Exception? ex)
    {
        string body = ex is null ? message : message + "\r\n\r\n" + ex.Message;
        MessageBox.Show(this, body, "Batch Rename Studio Pro", MessageBoxButtons.OK, MessageBoxIcon.Warning);
    }

    // --------------------------------------------------------------- drag & drop

    private void OnDragEnter(object? sender, DragEventArgs e)
    {
        if (e.Data?.GetDataPresent(DataFormats.FileDrop) == true)
        {
            e.Effect = DragDropEffects.Copy;
        }
    }

    private void OnDragDrop(object? sender, DragEventArgs e)
    {
        if (e.Data?.GetData(DataFormats.FileDrop) is not string[] paths || paths.Length == 0)
        {
            return;
        }

        string first = paths[0];
        string? folder = Directory.Exists(first) ? first : Path.GetDirectoryName(first);
        if (!string.IsNullOrEmpty(folder))
        {
            _txtFolder.Text = folder;
            Recompute();
        }
    }
}

