using System.Globalization;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

public static class ExitCodes
{
    public const int Success = 0;
    public const int RuntimeError = 1;
    public const int UsageError = 2;
}

/// <summary>
/// Implements the two fixed headless contracts. Neither of them touches the file system apart
/// from reading the folder listing and writing the requested report.
/// </summary>
public static class HeadlessRunner
{
    public const string UsageText = """
        Batch Rename Studio Pro

          BatchRenameStudio.exe
              Launch the graphical rule editor.

          BatchRenameStudio.exe --plan    --dir <folder> --rules <rules.json> --out <plan.json>
              Write the rename plan. Renames nothing.

          BatchRenameStudio.exe --explain --dir <folder> --rules <rules.json> --out <trace.json>
              Write the per-step trace. Renames nothing.

          BatchRenameStudio.exe --help | --version

        Exit codes: 0 success, 1 runtime error, 2 usage error.
        """;

    public static int Run(string[] args)
    {
        var stdout = Console.Out;
        var stderr = Console.Error;

        try
        {
            if (args.Any(a => a is "--help" or "-h" or "/?"))
            {
                stderr.WriteLine(UsageText);
                return ExitCodes.Success;
            }

            if (args.Any(a => a is "--version" or "-v"))
            {
                stdout.WriteLine("BatchRenameStudio 1.0.0");
                return ExitCodes.Success;
            }

            bool plan = args.Contains("--plan");
            bool explain = args.Contains("--explain");

            if (plan && explain)
            {
                stderr.WriteLine("error: --plan and --explain are mutually exclusive.");
                return ExitCodes.UsageError;
            }

            if (!plan && !explain)
            {
                stderr.WriteLine("error: expected --plan or --explain.");
                stderr.WriteLine(UsageText);
                return ExitCodes.UsageError;
            }

            if (!TryGetOption(args, "--dir", out string dir, stderr) ||
                !TryGetOption(args, "--rules", out string rulesPath, stderr) ||
                !TryGetOption(args, "--out", out string outPath, stderr))
            {
                return ExitCodes.UsageError;
            }

            if (!Directory.Exists(dir))
            {
                stderr.WriteLine($"error: folder not found: {dir}");
                return ExitCodes.RuntimeError;
            }

            if (!File.Exists(rulesPath))
            {
                stderr.WriteLine($"error: rules file not found: {rulesPath}");
                return ExitCodes.RuntimeError;
            }

            RuleSet rules;
            try
            {
                rules = StepJson.LoadRuleSet(rulesPath);
            }
            catch (RuleSetException ex)
            {
                stderr.WriteLine($"error: {ex.Message}");
                return ExitCodes.RuntimeError;
            }

            var result = RenameEngine.Run(dir, rules);

            if (plan)
            {
                ReportWriter.WriteFile(outPath, ReportWriter.BuildPlan(result));
                var s = result.Summary;
                stdout.WriteLine(string.Format(
                    CultureInfo.InvariantCulture,
                    "plan: total={0} ok={1} collision={2} unchanged={3} invalid={4} -> {5}",
                    s.Total, s.Ok, s.Collision, s.Unchanged, s.Invalid, Path.GetFullPath(outPath)));
            }
            else
            {
                ReportWriter.WriteFile(outPath, ReportWriter.BuildTrace(result));
                stdout.WriteLine(string.Format(
                    CultureInfo.InvariantCulture,
                    "explain: files={0} steps={1} -> {2}",
                    result.Items.Count, rules.Steps.Count, Path.GetFullPath(outPath)));
            }

            stdout.Flush();
            return ExitCodes.Success;
        }
        catch (Exception ex)
        {
            stderr.WriteLine($"error: {ex.Message}");
            return ExitCodes.RuntimeError;
        }
    }

    private static bool TryGetOption(string[] args, string name, out string value, TextWriter stderr)
    {
        for (int i = 0; i < args.Length; i++)
        {
            if (!string.Equals(args[i], name, StringComparison.Ordinal))
            {
                continue;
            }

            if (i + 1 >= args.Length || args[i + 1].StartsWith("--", StringComparison.Ordinal))
            {
                stderr.WriteLine($"error: {name} requires a value.");
                value = "";
                return false;
            }

            value = args[i + 1];
            return true;
        }

        stderr.WriteLine($"error: missing required option {name}.");
        value = "";
        return false;
    }
}

