                return ExitCodes.Success;
            }

            if (args.Contains("--undo"))
            {
                return RunUndo(args, stdout, stderr);
            }

            bool plan = args.Contains("--plan");
            bool explain = args.Contains("--explain");
            bool apply = args.Contains("--apply");

            if ((plan ? 1 : 0) + (explain ? 1 : 0) + (apply ? 1 : 0) > 1)
            {
                stderr.WriteLine("error: --plan, --explain and --apply are mutually exclusive.");
                return ExitCodes.UsageError;
            }

            if (!plan && !explain && !apply)
            {
                stderr.WriteLine("error: expected --plan or --explain.");
                stderr.WriteLine(UsageText);
                return ExitCodes.UsageError;
            }

            if (!TryGetOption(args, "--dir", out string dir, stderr) ||
                !TryGetOption(args, "--rules", out string rulesPath, stderr))
            {
