private static int RunUndo(string[] args, TextWriter stdout, TextWriter stderr)
{
    if (!TryGetOption(args, "--undo", out string journalPath, stderr))
    {
        return ExitCodes.UsageError;
    }

    if (!File.Exists(journalPath))
    {
        stderr.WriteLine($"error: journal not found: {journalPath}");
        return ExitCodes.RuntimeError;
    }

    UndoBatch batch;
    try
    {
        batch = ReadJournal(journalPath);
    }
    catch (Exception ex)
    {
        stderr.WriteLine($"error: journal could not be read: {ex.Message}");
        return ExitCodes.RuntimeError;
    }

    var outcome = RenameApplier.Undo(batch);
    foreach (string error in outcome.Errors)
    {
        stderr.WriteLine($"warning: {error}");
    }

    stdout.WriteLine(string.Format(
        CultureInfo.InvariantCulture,
        "undo: restored={0} of={1} dir={2}",
        outcome.Renamed, batch.Actions.Count, batch.Directory));
    stdout.Flush();

    return outcome.Errors.Count == 0 ? ExitCodes.Success : ExitCodes.RuntimeError;
}

private static UndoBatch ReadJournal(string path)
{
    var root = System.Text.Json.Nodes.JsonNode.Parse(File.ReadAllText(path)) as System.Text.Json.Nodes.JsonObject
               ?? throw new InvalidDataException("root is not an object");

    var actions = new List<RenameAction>();
    if (root["actions"] is System.Text.Json.Nodes.JsonArray array)
    {
        foreach (var node in array)
        {
            if (node is System.Text.Json.Nodes.JsonObject entry)
            {
                string from = StepJson.AsString(entry["from"], "");
                string to = StepJson.AsString(entry["to"], "");
                if (from.Length > 0 && to.Length > 0)
                {
                    actions.Add(new RenameAction(from, to));
                }
            }
        }
    }

    return new UndoBatch
    {
        Id = StepJson.AsString(root["id"], ""),
        TimestampUtc = StepJson.AsString(root["timestampUtc"], ""),
        Directory = StepJson.AsString(root["directory"], ""),
        Actions = actions,
    };
}

