private static void SafeSplit(SplitContainer container, int distance)
{
    try
    {
        int span = container.Orientation == Orientation.Horizontal ? container.Height : container.Width;
        int min = container.Panel1MinSize;
        int max = span - container.Panel2MinSize - container.SplitterWidth;
        if (max > min)
        {
            container.SplitterDistance = Math.Clamp(distance, min, max);
        }
    }
    catch (InvalidOperationException)
    {
        // The container is too small to honour the request; the default split is fine.
    }
}

