/// <summary>
/// Sets the split position first and the panel minimums afterwards. Doing it the other way
/// round throws, because a freshly built container is 150x100 with a 50px split.
/// </summary>
private static void SafeSplit(SplitContainer container, int distance, int min1, int min2)
{
    try
    {
        int span = container.Orientation == Orientation.Horizontal ? container.Height : container.Width;
        int available = span - container.SplitterWidth;
        if (available <= 20)
        {
            return;
        }

        int low = Math.Min(min1, available / 3);
        int high = available - Math.Min(min2, available / 3);
        if (high <= low)
        {
            return;
        }

        container.SplitterDistance = Math.Clamp(distance, low, high);
        container.Panel1MinSize = Math.Min(min1, container.SplitterDistance);
        container.Panel2MinSize = Math.Min(min2, available - container.SplitterDistance);
    }
    catch (Exception ex) when (ex is InvalidOperationException or ArgumentException)
    {
        // Too small to honour the request; the default split stays and stays usable.
    }
}

