using System.Runtime.InteropServices;
using BatchRenameStudio.Cli;
using BatchRenameStudio.Ui;

namespace BatchRenameStudio;

internal static class Program
{
    private const int AttachParentProcess = -1;

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool AttachConsole(int dwProcessId);

    [STAThread]
    private static int Main(string[] args)
    {
        if (args.Length > 0)
        {
            // A WinExe has no console of its own. Borrowing the launching shell's console lets
            // the summary line reach the user; when stdout is redirected the inherited handle
            // wins and the redirection still works.
            try
            {
                AttachConsole(AttachParentProcess);
            }
            catch (DllNotFoundException)
            {
                // Non-Windows host or a stripped kernel32: fall through, redirection still works.
            }

            return HeadlessRunner.Run(args);
        }

        Application.EnableVisualStyles();
        Application.SetCompatibleTextRenderingDefault(false);
        Application.SetHighDpiMode(HighDpiMode.PerMonitorV2);

        // A GUI failure must announce itself rather than vanish: without these the process
        // would exit silently with a native error code and no explanation anywhere.
        Application.SetUnhandledExceptionMode(UnhandledExceptionMode.CatchException);
        Application.ThreadException += (_, e) => ReportFatal(e.Exception);
        AppDomain.CurrentDomain.UnhandledException += (_, e) => ReportFatal(e.ExceptionObject as Exception);

        try
        {
            Application.Run(new MainForm());
        }
        catch (Exception ex)
        {
            ReportFatal(ex);
            return 1;
        }

        return 0;
    }

    private static void ReportFatal(Exception? ex)
    {
        if (ex is null)
        {
            return;
        }

        string logPath = Path.Combine(Path.GetTempPath(), "BatchRenameStudio-crash.log");
        try
        {
            File.AppendAllText(logPath, $"{DateTime.Now:u}  {ex}{Environment.NewLine}{Environment.NewLine}");
        }
        catch (IOException)
        {
            logPath = "(log could not be written)";
        }

        MessageBox.Show(
            $"Batch Rename Studio Pro hit an unexpected error.\r\n\r\n{ex.GetType().Name}: {ex.Message}\r\n\r\nDetails were written to:\r\n{logPath}",
            "Batch Rename Studio Pro",
            MessageBoxButtons.OK,
            MessageBoxIcon.Error);
    }
}

