param([string]$Png, [int]$WaitMs = 5000, [string[]]$AppArgs = @())

Add-Type -AssemblyName System.Drawing

Add-Type @"
using System;
using System.Runtime.InteropServices;
public static class Win {
    [DllImport("user32.dll")] public static extern bool PrintWindow(IntPtr h, IntPtr hdc, uint flags);
    [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
    [DllImport("user32.dll")] public static extern bool SetProcessDPIAware();
    [StructLayout(LayoutKind.Sequential)] public struct RECT { public int Left, Top, Right, Bottom; }
}
"@

[void][Win]::SetProcessDPIAware()

$exe = 'D:\BenchRuns\XL-CAL-01\src\BatchRenameStudio\bin\Release\net8.0-windows\BatchRenameStudio.exe'
if ($AppArgs.Count -gt 0) {
    $proc = Start-Process -FilePath $exe -ArgumentList $AppArgs -PassThru
} else {
    $proc = Start-Process -FilePath $exe -PassThru
}
Start-Sleep -Milliseconds $WaitMs

if ($proc.HasExited) {
    Write-Output "PROCESS EXITED EARLY: code=$($proc.ExitCode)"
    exit 1
}

$proc.Refresh()
$h = $proc.MainWindowHandle
Write-Output "MainWindowHandle=$h  Title='$($proc.MainWindowTitle)'  Responding=$($proc.Responding)"

if ($h -ne [IntPtr]::Zero) {
    $r = New-Object Win+RECT
    [void][Win]::GetWindowRect($h, [ref]$r)
    $w = $r.Right - $r.Left
    $ht = $r.Bottom - $r.Top
    Write-Output "WindowSize = ${w}x${ht}"

    $bmp = New-Object System.Drawing.Bitmap $w, $ht
    $g = [System.Drawing.Graphics]::FromImage($bmp)
    $hdc = $g.GetHdc()
    # PW_RENDERFULLCONTENT (2): renders this window only, no screen scraping,
    # and works without stealing the foreground.
    $ok = [Win]::PrintWindow($h, $hdc, 2)
    $g.ReleaseHdc($hdc)
    $g.Dispose()
    $bmp.Save($Png, [System.Drawing.Imaging.ImageFormat]::Png)
