$sp='C:\Users\USER\AppData\Local\Temp\claude\D--BenchRuns-XL-CAL-01\884d8235-25b2-42ba-ad10-5161834ce233\scratchpad'
foreach($s in @('photo-sequence','web-slug','invoice-normalise')){
  $res = & "$sp\run.ps1" -Mode '--plan' -Dir "$sp\fx" -Rules "D:\BenchRuns\XL-CAL-01\samples\$s.json" -Out "$sp\out\$s.json"
  Write-Output "== $s exit=$($res.Exit)"
  $j = Get-Content -LiteralPath "$sp\out\$s.json" -Raw -Encoding UTF8 | ConvertFrom-Json
  foreach($i in $j.items){ Write-Output ("   {0,-20} -> {1,-30} [{2}]" -f $i.original,$i.proposed,$i.status) }
}

$sp='C:\Users\USER\AppData\Local\Temp\claude\D--BenchRuns-XL-CAL-01\884d8235-25b2-42ba-ad10-5161834ce233\scratchpad'
$fail=0
$before=(Get-ChildItem -LiteralPath "$sp\fx" -Force | Sort-Object Name | ForEach-Object Name) -join '|'
foreach($r in @('r1-basic','r2-status','r3-collision','r4-existing','tA','tB','tC','tD','tInv','tLong','tEmpty','tEdge')){
  foreach($mode in @('--plan','--explain')){
    $suffix = if($mode -eq '--plan'){'plan'}else{'trace'}
    $res = & "$sp\run.ps1" -Mode $mode -Dir "$sp\fx" -Rules "$sp\rules\$r.json" -Out "$sp\out\rg-$r.$suffix.json"
    $lines = ($res.Stdout -split "`n" | Where-Object { $_.Trim() -ne '' }).Count
    if($res.Exit -ne 0 -or $lines -ne 1){ Write-Output "FAIL $r $mode exit=$($res.Exit) lines=$lines"; $fail++ }
  }
}
$after=(Get-ChildItem -LiteralPath "$sp\fx" -Force | Sort-Object Name | ForEach-Object Name) -join '|'
Write-Output "24 runs, failures=$fail"
Write-Output "FOLDER UNTOUCHED: $($before -eq $after)"
# empty folder + zero-step rules
New-Item -ItemType Directory -Force -Path "$sp\empty" | Out-Null
'{ }' | Out-File "$sp\rules\tNone.json" -Encoding utf8
$e = & "$sp\run.ps1" -Mode '--plan' -Dir "$sp\empty" -Rules "$sp\rules\tNone.json" -Out "$sp\out\empty.json"
Write-Output "empty folder: exit=$($e.Exit) | $($e.Stdout.Trim())"
Get-Content "$sp\out\empty.json" -Raw
$z = & "$sp\run.ps1" -Mode '--explain' -Dir "$sp\ops" -Rules "$sp\rules\tNone.json" -Out "$sp\out\zerostep.json"
Write-Output "zero steps: exit=$($z.Exit) | $($z.Stdout.Trim())"
(Get-Content "$sp\out\zerostep.json" -Raw -Encoding UTF8 | ConvertFrom-Json).files | ForEach-Object { "   $($_.original) -> $($_.proposed) [$($_.status)] steps=$($_.steps.Count)" }
